mapper.select:
/* AppTbm01Mapper.selectMyAttendance */
SELECT
      ATTENDANCE_CD          AS attendanceCd
    , SESSION_CD             AS sessionCd
    , ENTRY_AT               AS entryAt
    , ENTRY_DISTANCE_M       AS entryDistanceM
    , EXIT_AT                AS exitAt
    , COMPLETION_STATUS_CD   AS completionStatusCd
FROM TB_TBM_ATTENDANCE
WHERE CMPNY_CD = #{cmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND USER_TYPE_CD = #{userTypeCd}
  AND USER_CD = #{userCd}
  AND DEL_YN = 'N'

/* AppTbm01Mapper.countRecentPwdFail */
SELECT
    COUNT(*)
FROM TB_TBM_PWD_FAIL
WHERE CMPNY_CD = #{cmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND PWD_TYPE_CD = #{pwdTypeCd}
  AND USER_CD = #{userCd}
  AND ATTEMPTED_AT >= DATE_SUB(NOW(), INTERVAL #{lockWindowSeconds} SECOND)

mapper.insert:
/* AppTbm01Mapper.insertPwdFail */
INSERT INTO TB_TBM_PWD_FAIL (
      CMPNY_CD
    , SESSION_CD
    , PWD_TYPE_CD
    , USER_TYPE_CD
    , USER_CD
    , ATTEMPTED_AT
    , INSERT_NO
    , INSERT_DATE
)
VALUES (
      #{cmpnyCd}
    , #{sessionCd}
    , #{pwdTypeCd}
    , #{userTypeCd}
    , #{userCd}
    , NOW()
    , #{insertNo}
    , NOW()
)

mapper.delete:
/* AppTbm01Mapper.deletePwdFail */
DELETE FROM TB_TBM_PWD_FAIL
WHERE CMPNY_CD = #{cmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND PWD_TYPE_CD = #{pwdTypeCd}
  AND USER_CD = #{userCd}

mapper.insert:
/* AppTbm01Mapper.insertAttendance */
INSERT INTO TB_TBM_ATTENDANCE (
      ATTENDANCE_CD
    , CMPNY_CD
    , SESSION_CD
    , USER_TYPE_CD
    , USER_CD
    , ENTRY_TYPE_CD
    , ENTRY_AT
    , ENTRY_GPS_LAT
    , ENTRY_GPS_LON
    , ENTRY_DISTANCE_M
    , DEL_YN
    , INSERT_NO
    , INSERT_DATE
    , UPDATE_NO
    , UPDATE_DATE
)
VALUES (
      CONCAT('A', DATE_FORMAT(NOW(), '%Y%m%d'), FNC_CMM_SEQ_NEXTVAL(#{cmpnyCd}, 'TBM_ATTENDANCE_CD'))
    , #{cmpnyCd}
    , #{sessionCd}
    , #{userTypeCd}
    , #{userCd}
    , #{entryTypeCd}
    , NOW()
    , #{lat}
    , #{lon}
    , #{distanceM}
    , 'N'
    , #{insertNo}
    , NOW()
    , #{insertNo}
    , NOW()
)

mapper.update:
/* AppTbm01Mapper.updateExit */
UPDATE TB_TBM_ATTENDANCE
SET
      EXIT_TYPE_CD           = #{exitTypeCd}
    , EXIT_AT                = NOW()
    , EXIT_SIGN_FILE_MGMT_CD = #{exitSignFileMgmtCd}
    , COMPLETION_STATUS_CD   = #{completionStatusCd}
    , STATUS_UPDATED_BY      = #{updateNo}
    , STATUS_UPDATED_AT      = NOW()
    , UPDATE_NO              = #{updateNo}
    , UPDATE_DATE            = NOW()
WHERE CMPNY_CD = #{cmpnyCd}
  AND SESSION_CD = #{sessionCd}
  AND USER_TYPE_CD = #{userTypeCd}
  AND USER_CD = #{userCd}
  AND DEL_YN = 'N'
  AND EXIT_AT IS NULL
